#pragma once
// ============================================================================
//  NeuralEngine - the NEURAL side of the brain.
//  A small multi-layer GRU trained on the Groove MIDI Dataset (13.6 h of
//  professional drummers, CC BY 4.0) plus bars generated by The Hammer's own
//  Playbook (so it also knows metal, orchestral, cajón, minimal...) plus any
//  MIDI you drop into training/my_midi/<style>/. It writes one 16th-note step at a time,
//  conditioned on: style, intensity, what the Ears hear at that step, the
//  position in the bar and whether it should be playing a fill. It keeps its
//  hidden state between bars so it "remembers" what it just played.
//
//  Pure C++ inference, no allocations in generate(), < 1 ms per bar.
//  If no trained model is present, a Playbook-based improviser stands in
//  (and the UI says so).
// ============================================================================
#include "StyleLibrary.h"
#include "PlaybookEngine.h"
#include <vector>
#include <string>

namespace hammer
{
constexpr int kNeuralLanes = 9;  // kick, snare, hh closed, hh open, tom low, tom mid, tom high, crash, ride
// prev step (27) + GMD style mix (18) + Hammer style one-hot (12) + intensity + listen (3) + position (5) + fill
constexpr int kNeuralIn = 27 + kNumGmdStyles + NumStyles + 1 + 3 + 5 + 1; // = 67
constexpr int kNeuralOut = 27;

class GruNetwork
{
public:
    bool loadFromJson (const std::string& json, std::string& error);
    bool isValid() const { return valid; }
    int hiddenSize() const { return hidden; }
    int numLayers() const { return (int) layers.size(); }

    void resetState();
    void decayState (float k);
    // One step. in[kNeuralIn] -> out[kNeuralOut] (raw: logits / pre-activations)
    void step (const float* in, float* out);

    // Self-test against vectors exported by the trainer. Returns max abs error, <0 if no test data.
    float runSelfTest();
    std::string description;

private:
    struct Layer
    {
        int in = 0, h = 0;
        std::vector<float> wih, whh, bih, bhh; // [3h x in], [3h x h], [3h], [3h]
        std::vector<float> state, gx, gh;
    };
    std::vector<Layer> layers;
    std::vector<float> outW, outB, buf;
    int hidden = 0;
    bool valid = false;
    std::vector<std::vector<float>> testIn, testOut;
};

class NeuralEngine
{
public:
    NeuralEngine();
    // Load the embedded model (if built with one) or a user model file.
    void loadDefault();
    bool loadFile (const std::string& path);
    bool hasModel() const { return net.isValid(); }
    const std::string& status() const { return statusText; }

    void reset();
    void onStyleChange();

    // U = common random numbers so neural & playbook realisations stay coherent.
    void generate (const BrainContext& ctx, LaneGrid& out, Rng& rng, const float (*U)[kMaxTicks],
                   float temperature);

    static int neuralToLane (int nl, int styleId, float aggression);
    // Inverse mapping used to turn Playbook grooves into training data (-1 = not learned)
    static int laneToNeural (int lane, int styleId);
    float lastSelfTestError = -1.f;

private:
    void generateFallback (const BrainContext& ctx, LaneGrid& out, Rng& rng);

    GruNetwork net;
    PlaybookEngine improviser;
    LaneGrid memory;      // fallback: last bar for Markov-style variation
    bool haveMemory = false;
    float prevStep[27] {};
    std::string statusText;
};
} // namespace hammer
